458	    constexpr int sidecar_ld = 64;
459	    constexpr long long matrix_elements = 256LL * 256LL;
460	    constexpr long long sidecar_tile_elements = 64LL * 64LL;
461	    const int block = blockIdx.x;
462	    const int sample = block & 63;
463	    const int task = block >> 6;
464	    const int panel_tile = 1 + (task >> 1);
465	    const int panel_half = task & 1;
466	    const long long sample_base = sample * matrix_elements;
467	    const long long panel_output_index =
468	        sample_base + panel_tile * 64 + panel_half * 32;
469	    const long long sidecar_index =
470	        (sample * 5LL + panel_tile - 1) * sidecar_tile_elements
471	        + panel_half * 32;
472	
473	    const int row = threadIdx.x >> 3;
474	    const int col = (threadIdx.x & 7) * 4;
475	    #pragma unroll
476	    for (int load = 0; load < 4; ++load) {
477	        const int current_row = row + load * 16;
478	        const float4 panel_values = *reinterpret_cast<const float4*>(
479	            panel + current_row * panel_ld + col);
480	        *reinterpret_cast<float4*>(
481	            output + panel_output_index + current_row * output_ld + col) =
482	            panel_values;
483	        __half2* packed = reinterpret_cast<__half2*>(
484	            sidecar + sidecar_index + current_row * sidecar_ld + col);
485	        packed[0] = __floats2half2_rn(panel_values.x, panel_values.y);
486	        packed[1] = __floats2half2_rn(panel_values.z, panel_values.w);
487	    }
488	
489	    if (task == 0) {
490	        const int factor_row = threadIdx.x >> 4;
491	        const int factor_col = (threadIdx.x & 15) * 4;
492	        #pragma unroll
493	        for (int load = 0; load < 8; ++load) {
494	            const int current_row = factor_row + load * 8;
495	            if (current_row > factor_col + 3) continue;
496	            const float4 factor_values = *reinterpret_cast<const float4*>(
497	                factor + current_row * factor_ld + factor_col);
