499	                output + sample_base + current_row * output_ld + factor_col;
500	            if (current_row <= factor_col) {
501	                *reinterpret_cast<float4*>(destination) = factor_values;
502	            } else {
503	                if (current_row <= factor_col + 1) {
504	                    destination[1] = factor_values.y;
505	                }
506	                if (current_row <= factor_col + 2) {
507	                    destination[2] = factor_values.z;
508	                }
509	                destination[3] = factor_values.w;
510	            }
511	        }
512	    }
